import { useMemo, useReducer, useState } from "react";
const initial={projects:[{id:1,name:"Website redesign",status:"active",owner:"Mina"},{id:2,name:"Mobile onboarding",status:"planned",owner:"Ravi"}],selectedId:1};
function reducer(state,action){switch(action.type){case"selected":return{...state,selectedId:action.id};case"added":return{...state,projects:[...state.projects,action.project],selectedId:action.project.id};default:throw new Error("Unknown action");}}
function ProjectList({projects,selectedId,onSelect}){return <ul>{projects.map(p=><li key={p.id}><button aria-pressed={p.id===selectedId} onClick={()=>onSelect(p.id)}>{p.name} — {p.status}</button></li>)}</ul>}
function AddProject({onAdd}){const[name,setName]=useState("");const[owner,setOwner]=useState("");function submit(e){e.preventDefault();if(!name.trim()||!owner.trim())return;onAdd({id:Date.now(),name:name.trim(),owner:owner.trim(),status:"planned"});setName("");setOwner("");}return <form onSubmit={submit}><label>Project name<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Owner<input value={owner} onChange={e=>setOwner(e.target.value)}/></label><button>Add project</button></form>}
export default function App(){const[state,dispatch]=useReducer(reducer,initial);const[q,setQ]=useState("");const visible=useMemo(()=>state.projects.filter(p=>`${p.name} ${p.owner} ${p.status}`.toLowerCase().includes(q.toLowerCase())),[q,state.projects]);const selected=state.projects.find(p=>p.id===state.selectedId);return <main><h1>Project Dashboard</h1><label>Search projects<input value={q} onChange={e=>setQ(e.target.value)}/></label><ProjectList projects={visible} selectedId={state.selectedId} onSelect={id=>dispatch({type:"selected",id})}/>{selected&&<section><h2>{selected.name}</h2><p>Owner: {selected.owner}</p><p>Status: {selected.status}</p></section>}<AddProject onAdd={p=>dispatch({type:"added",project:p})}/></main>}

